'use strict';
// ============================================================
//  探索フィールド：ミャオニアの区画データと、区画ごとの地形・小物の生成
//  区画はゲート（出入口）でつながる。座標は区画中央が原点、北が -Z（m）。
//  地形マップ（map）のある区画は座標がマス（列, 行）。
// ============================================================
// exits: side = n/s/e/w（辺）、at = 辺に沿った位置、to = 行き先
// town: 人が暮らす区画（敵が出ない）／ calmAfter: そのステージをクリアすると敵が出なくなる
// npcs[].v: [[条件, 台詞...]]（条件 'scene:ID' 'clear:ステージ' 'done' 'flag:名前'。後ろのものほど優先）
// npcs[].shop: weapon / item / inn / fish（話しかけると店）
// naps / sleepwalk の name：まだ名前を知らない子の呼び名（なければ speakerName）
// notes[].when / until: その条件を満たしてから出る／満たすと消える
// notes：F で調べられるもの。道をふさがないよう、実物の上に光る目印を出す
//   post / board: [札の文, 小さな文]（道しるべ／二本脚の看板を立てる。札の向きは face）
//   mark: 目印の高さ、または [dx, 高さ, dz]（区画の小物が実物。at はその小物の位置）
//   reach: 調べられる距離（大きな小物のとき。既定 2m）。どれも書かないと石碑を立てる
// bg: 空と光（js/gfx/env.js の THEMES。省略時は章の bg）
// ニャハハ王国に笑顔が戻ったか（第三章の最後の戦いのあと）：城下町と城の空・床・家の色
function kingdomJoy() { return typeof Save !== 'undefined' && !!(Save.data && Save.data.cleared && Save.data.cleared['3-3']); }
